select jsonb_build_object('functions',(select jsonb_object_agg(p.oid::regprocedure::text,jsonb_build_object('body_md5',md5(p.prosrc),'acl',p.proacl::text,'config',p.proconfig,'owner',pg_get_userbyid(p.proowner),'security_definer',p.prosecdef)) from pg_proc p where p.oid in ('public.avalia_plus_create_assessment_from_bank(jsonb)'::regprocedure,'public.avalia_plus_replace_assessment_items(uuid,jsonb)'::regprocedure,'public.current_question_bank_role()'::regprocedure,'public.avalia_plus_can_author_items()'::regprocedure,'public.has_question_bank_role(text[])'::regprocedure,'school_category_private.actor_context(jsonb)'::regprocedure,'school_category_private.assessment_assert_question(uuid,uuid,uuid)'::regprocedure,'school_category_private.assessment_content_write_guard()'::regprocedure)),'triggers',(select jsonb_object_agg(t.tgname,jsonb_build_object('definition',pg_get_triggerdef(t.oid),'enabled',t.tgenabled)) from pg_trigger t where t.tgname in ('fase3_assessment_question_guard','fase3_assessment_delete_guard','fase3_assessment_publication_guard')),'ledger',(select jsonb_build_object('count',count(*),'latest',max(version),'hash',md5(string_agg(version||':'||coalesce(name,''),',' order by version))) from supabase_migrations.schema_migrations)) as snapshot;
